<?php
require 'config.php';require 'auth.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){require_login();$facilityId=(int)($_POST['facility_id']??0);$comment=trim($_POST['comment']??'');$rating=(int)($_POST['rating']??0);$uid=current_user_id();if($facilityId<1||$comment===''||$rating<1||$rating>5)$error='Choose a facility, enter a comment and select a rating.';else{$stmt=$conn->prepare('INSERT INTO testimonials(user_id,facility_id,comment,rating) VALUES(?,?,?,?)');$stmt->bind_param('iisi',$uid,$facilityId,$comment,$rating);if($stmt->execute()){header('Location: testimonials.php');exit;}$error='Could not post your comment.';}}$facilities=$conn->query('SELECT id,facility_name FROM facilities WHERE is_active=1 ORDER BY facility_name')->fetch_all(MYSQLI_ASSOC);$testimonials=$conn->query('SELECT t.*,u.name user_name,f.facility_name FROM testimonials t JOIN users u ON u.id=t.user_id JOIN facilities f ON f.id=t.facility_id ORDER BY t.created_at DESC')->fetch_all(MYSQLI_ASSOC);$pageTitle='Testimonials';require 'partials/header.php';?>
<div class="page-header"><h1>Testimonials</h1><p>What students say about our sports facilities.</p></div><?php if(current_user_id()):?><div class="form-card" style="margin-bottom:24px;max-width:600px"><h2>Leave a Comment</h2><?php if($error):?><p class="alert alert-error"><?=htmlspecialchars($error)?></p><?php endif;?><form method="post"><label>Facility <select name="facility_id" required><option value="">-- Select --</option><?php foreach($facilities as $f):?><option value="<?=(int)$f['id']?>"><?=htmlspecialchars($f['facility_name'])?></option><?php endforeach;?></select></label><label>Rating <select name="rating"><option value="5">5 - Excellent</option><option value="4">4 - Good</option><option value="3">3 - Okay</option><option value="2">2 - Poor</option><option value="1">1 - Bad</option></select></label><label>Comment <textarea name="comment" rows="3" maxlength="1000" required></textarea></label><button>Post Comment</button></form></div><?php else:?><p><a href="login.php">Login</a> to leave a comment.</p><?php endif;?>
<?php if(!$testimonials):?><div class="empty-state"><p>No comments yet.</p></div><?php else:?><div class="testimonial-list"><?php foreach($testimonials as $t):?><div class="testimonial-card"><span class="badge badge-accent"><?=htmlspecialchars($t['facility_name'])?></span><div class="testimonial-stars"><?=str_repeat('&#9733;',(int)$t['rating']).str_repeat('&#9734;',5-(int)$t['rating'])?></div><p class="testimonial-comment"><?=nl2br(htmlspecialchars($t['comment']))?></p><div class="testimonial-meta"><span><?=htmlspecialchars($t['user_name'])?> &middot; <?=htmlspecialchars(date('d M Y',strtotime($t['created_at'])))?></span><?php if(current_user_id()==$t['user_id']):?><form method="post" action="testimonial_delete.php" style="display:inline"><input type="hidden" name="id" value="<?=(int)$t['id']?>"><button class="btn-small btn-danger">Delete</button></form><?php endif;?></div><?php if($t['admin_reply']!==null):?><div class="admin-reply"><strong>Reply from <?=htmlspecialchars($t['admin_reply_name']??'Admin')?></strong><p><?=nl2br(htmlspecialchars($t['admin_reply']))?></p><small><?=htmlspecialchars(date('d M Y',strtotime($t['admin_replied_at'])))?></small></div><?php endif;?></div><?php endforeach;?></div><?php endif;?><?php require 'partials/footer.php';?>
